\shortans{3,3}

\loigiai{
$\sqrt[3]{2 - 3 x}=-2\Rightarrow 2 - 3 x=-8\Rightarrow -3x=-10\Rightarrow x=\dfrac{10}{3}=3,3$.
}\end{ex}

\begin{ex}%[9D3H4-1]
